import json
import sys

def process_file(path, lines):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            content = f.read().split('\n')
            
        lines = sorted(set(lines), reverse=True)
        for l in lines:
            if l >= len(content): continue
            line = content[l]
            
            if "{" in line or "}" in line:
                continue
            
            if "if " in line and "return" in line and ";" in line:
                parts = line.split(")")
                if len(parts) >= 2:
                    idx = line.rfind(")")
                    before = line[:idx+1]
                    after = line[idx+1:]
                    content[l] = before + " {" + after + " }"
            elif "if " not in line and line.strip().endswith(";"):
                content[l] = "  { " + line.strip() + " }"
            
        with open(path, 'w', encoding='utf-8') as f:
            f.write('\n'.join(content))
    except Exception:
        pass

